/**
 * A parser to parse JSON into a parse tree of {@link JsonElement}s.
 *
 * @author Inderjeet Singh
 * @author Joel Leitch
 * @since 1.3
 */
public final class JsonParser {
  /**
   * @deprecated No need to instantiate this class, use the static methods instead.
   */
